mapper.select:
SELECT SERVERIP serverIp, /* 服务器IP */ SERVERPORT serverPort, /* 服务器端口号 */ SERVERNAME serverName, /*服务名（数据库方式下为服务名）*/ USERNAME userName, /* 用户名 */ PASSWORD password, /* 服务器登录密码 */ SERVERTYPE serverType, /* 服务器登录类型 */ STATUS status, /* 状态 */ SYSTEMID systemID, /* 系统ID */ REMOTE_PATH remotePath, /* 远程路径 */ LOCAL_PATH localPath, /* 本地路径 */ RS rsStatus /* 发送和接收 */
, #{execId} AS execInfoId
FROM VAL_INTERF_SERVER_INFO WHERE 1 = 1 AND STATUS = 'Y'
AND RS = #{rsStatus}
AND SYSTEMID = #{SYSTEMID}
AND SYSTEMID IN ( SELECT A.SYSTEMID FROM VAL_INTERF_TEMPLATE A WHERE EXISTS ( SELECT 1 FROM VAL_INTERF_DEFINE B WHERE A.INTERF_ID = B.INTERF_ID AND
B.INTERF_E_NAME = #{item,jdbcType=VARCHAR}
) )

SELECT TMP_C_NAME tmpCName, TMP_E_NAME tmpEName, DTO_NAME dtoName, INTERF_ID interfId, TMP_TYPE tmpType, SYSTEMID systemid FROM VAL_INTERF_TEMPLATE WHERE 1 = 1
AND INTERF_ID IN (SELECT INTERF_ID FROM VAL_INTERF_DEFINE WHERE 1=1
INTERF_E_NAME = #{item,jdbcType=VARCHAR}
)
